class Context:
    """The template context holds the variables of a template.  It stores the
    values passed to the template and also the names the template exports.
    Creating instances is neither supported nor useful as it's created
    automatically at various stages of the template evaluation and should not
    be created by hand.

    The context is immutable.  Modifications on :attr:`parent` **must not**
    happen and modifications on :attr:`vars` are allowed from generated
    template code only.  Template filters and global functions marked as
    :func:`pass_context` get the active context passed as first argument
    and are allowed to access the context read-only.

    The template context supports read only dict operations (`get`,
    `keys`, `values`, `items`, `iterkeys`, `itervalues`, `iteritems`,
    `__getitem__`, `__contains__`).  Additionally there is a :meth:`resolve`
    method that doesn't fail with a `KeyError` but returns an
    :class:`Undefined` object for missing variables.

    Acts as a mediator between template execution and environment services,
    coordinating filter invocation, test evaluation, and attribute resolution
    through a unified dispatch interface.
    """

    _attr_resolution_handler: t.ClassVar[
        t.Optional[t.Callable[..., t.Any]]
    ] = None

    _filter_test_cache: t.ClassVar[t.Dict[str, t.Any]] = {}

    def __init__(
        self,
        environment: "Environment",
        parent: t.Dict[str, t.Any],
        name: t.Optional[str],
        blocks: t.Dict[str, t.Callable[["Context"], t.Iterator[str]]],
        globals: t.Optional[t.MutableMapping[str, t.Any]] = None,
    ):
        self.parent = parent
        self.vars: t.Dict[str, t.Any] = {}
        self.environment: Environment = environment
        self.eval_ctx = EvalContext(self.environment, name)
        self.exported_vars: t.Set[str] = set()
        self.name = name
        self.globals_keys = set() if globals is None else set(globals)
        self._eval_ctx_autoescape = self.eval_ctx.autoescape

        # create the initial mapping of blocks.  Whenever template inheritance
        # takes place the runtime will update this mapping with the new blocks
        # from the template.
        self.blocks = {k: [v] for k, v in blocks.items()}

        self.eval_ctx.bind_context_notify(self._on_eval_ctx_changed)

        self._register_dispatch_handlers()

    def _on_eval_ctx_changed(self, eval_ctx: "EvalContext") -> None:
        self._eval_ctx_autoescape = eval_ctx.autoescape

    @classmethod
    def _register_dispatch_handlers(cls) -> None:
        if cls._attr_resolution_handler is None:
            cls._attr_resolution_handler = cls._default_attr_resolve
        if not get_pass_arg_handler("context"):
            register_pass_arg_handler("context", cls._dispatch_pass_context)
            register_pass_arg_handler("eval_context", cls._dispatch_pass_eval_context)
            register_pass_arg_handler("environment", cls._dispatch_pass_environment)

    @staticmethod
    def _default_attr_resolve(
        environment: "Environment", item: t.Any, part: t.Union[str, int]
    ) -> t.Any:
        return environment.getitem(item, part)

    @staticmethod
    def _dispatch_pass_context(
        context: "Context", args: t.List[t.Any]
    ) -> t.List[t.Any]:
        args.insert(0, context)
        return args

    @staticmethod
    def _dispatch_pass_eval_context(
        context: "Context", args: t.List[t.Any]
    ) -> t.List[t.Any]:
        args.insert(0, context.eval_ctx)
        return args

    @staticmethod
    def _dispatch_pass_environment(
        context: "Context", args: t.List[t.Any]
    ) -> t.List[t.Any]:
        args.insert(0, context.environment)
        return args

    def invoke_filter(
        self,
        name: str,
        value: t.Any,
        args: t.Optional[t.Sequence[t.Any]] = None,
        kwargs: t.Optional[t.Mapping[str, t.Any]] = None,
    ) -> t.Any:
        return self.environment.call_filter(
            name, value, args, kwargs, self, self.eval_ctx
        )

    def invoke_test(
        self,
        name: str,
        value: t.Any,
        args: t.Optional[t.Sequence[t.Any]] = None,
        kwargs: t.Optional[t.Mapping[str, t.Any]] = None,
    ) -> t.Any:
        return self.environment.call_test(
            name, value, args, kwargs, self, self.eval_ctx
        )

    @classmethod
    def create(
        cls,
        environment: "Environment",
        template_name: t.Optional[str],
        blocks: t.Dict[str, t.Callable[["Context"], t.Iterator[str]]],
        vars: t.Optional[t.Dict[str, t.Any]] = None,
        shared: bool = False,
        globals: t.Optional[t.MutableMapping[str, t.Any]] = None,
        locals: t.Optional[t.Mapping[str, t.Any]] = None,
    ) -> "Context":
        return new_context(
            environment, template_name, blocks, vars, shared, globals, locals
        )

    def super(
        self, name: str, current: t.Callable[["Context"], t.Iterator[str]]
    ) -> t.Union["BlockReference", "Undefined"]:
        """Render a parent block."""
        try:
            blocks = self.blocks[name]
            index = blocks.index(current) + 1
            blocks[index]
        except LookupError:
            return self.environment.undefined(
                f"there is no parent block called {name!r}.", name="super"
            )
        return BlockReference(name, self, blocks, index)

    def get(self, key: str, default: t.Any = None) -> t.Any:
        """Look up a variable by name, or return a default if the key is
        not found.

        :param key: The variable name to look up.
        :param default: The value to return if the key is not found.
        """
        try:
            return self[key]
        except KeyError:
            return default

    def resolve(self, key: str) -> t.Union[t.Any, "Undefined"]:
        """Look up a variable by name, or return an :class:`Undefined`
        object if the key is not found.

        If you need to add custom behavior, override
        :meth:`resolve_or_missing`, not this method. The various lookup
        functions use that method, not this one.

        :param key: The variable name to look up.
        """
        rv = self.resolve_or_missing(key)

        if rv is missing:
            return self.environment.undefined(name=key)

        return rv

    def resolve_or_missing(self, key: str) -> t.Any:
        """Look up a variable by name, or return a ``missing`` sentinel
        if the key is not found.

        Override this method to add custom lookup behavior.
        :meth:`resolve`, :meth:`get`, and :meth:`__getitem__` use this
        method. Don't call this method directly.

        :param key: The variable name to look up.
        """
        if key in self.vars:
            return self.vars[key]

        if key in self.parent:
            return self.parent[key]

        return missing

    def get_exported(self) -> t.Dict[str, t.Any]:
        """Get a new dict with the exported variables."""
        return {k: self.vars[k] for k in self.exported_vars}

    def get_all(self) -> t.Dict[str, t.Any]:
        """Return the complete context as dict including the exported
        variables.  For optimizations reasons this might not return an
        actual copy so be careful with using it.
        """
        if not self.vars:
            return self.parent
        if not self.parent:
            return self.vars
        return dict(self.parent, **self.vars)

    @internalcode
    def call(
        __self,
        __obj: t.Callable[..., t.Any],
        *args: t.Any,
        **kwargs: t.Any,  # noqa: B902
    ) -> t.Union[t.Any, "Undefined"]:
        """Call the callable with the arguments and keyword arguments
        provided but inject the active context or environment as first
        argument if the callable has :func:`pass_context` or
        :func:`pass_environment`.
        """
        if __debug__:
            __traceback_hide__ = True  # noqa

        # Allow callable classes to take a context
        if (
            hasattr(__obj, "__call__")  # noqa: B004
            and _PassArg.from_obj(__obj.__call__) is not None
        ):
            __obj = __obj.__call__

        pass_arg = _PassArg.from_obj(__obj)

        if pass_arg is _PassArg.context:
            # the active context should have access to variables set in
            # loops and blocks without mutating the context itself
            if kwargs.get("_loop_vars"):
                __self = __self.derived(kwargs["_loop_vars"])
            if kwargs.get("_block_vars"):
                __self = __self.derived(kwargs["_block_vars"])
            args = (__self,) + args
        elif pass_arg is _PassArg.eval_context:
            args = (__self.eval_ctx,) + args
        elif pass_arg is _PassArg.environment:
            args = (__self.environment,) + args

        kwargs.pop("_block_vars", None)
        kwargs.pop("_loop_vars", None)

        try:
            return __obj(*args, **kwargs)
        except StopIteration:
            return __self.environment.undefined(
                "value was undefined because a callable raised a"
                " StopIteration exception"
            )

    def derived(self, locals: t.Optional[t.Dict[str, t.Any]] = None) -> "Context":
        """Internal helper function to create a derived context.  This is
        used in situations where the system needs a new context in the same
        template that is independent.
        """
        context = new_context(
            self.environment, self.name, {}, self.get_all(), True, None, locals
        )
        context.eval_ctx = self.eval_ctx
        context.blocks.update((k, list(v)) for k, v in self.blocks.items())
        return context

    def resolve_attribute(
        self, obj: t.Any, attribute: t.Union[str, int]
    ) -> t.Any:
        return self.environment.getitem(obj, attribute)

    def is_autoescape_active(self) -> bool:
        return self._eval_ctx_autoescape

    keys = _dict_method_all(dict.keys)
    values = _dict_method_all(dict.values)
    items = _dict_method_all(dict.items)

    def __contains__(self, name: str) -> bool:
        return name in self.vars or name in self.parent

    def __getitem__(self, key: str) -> t.Any:
        """Look up a variable by name with ``[]`` syntax, or raise a
        ``KeyError`` if the key is not found.
        """
        item = self.resolve_or_missing(key)

        if item is missing:
            raise KeyError(key)

        return item

    def __repr__(self) -> str:
        return f"<{type(self).__name__} {self.get_all()!r} of {self.name!r}>"

def test_custom_context(self):
        class CustomContext(Context):
            def resolve_or_missing(self, key):
                return "resolve-" + key

        class CustomEnvironment(Environment):
            context_class = CustomContext

        env = CustomEnvironment()
        tmpl = env.from_string("{{ foo }}")
        assert tmpl.render() == "resolve-foo"


def test_overlay_enable_async(env):
    assert not env.is_async
    assert not env.overlay().is_async
    env_async = env.overlay(enable_async=True)
    assert env_async.is_async
    assert not env_async.overlay(enable_async=False).is_async

