class VariableResolver:
    """Handles variable lookup and resolution logic.

    Encapsulates the strategy for finding variables in the template context,
    searching through local variables, parent scope, and handling the
    missing value sentinel.
    """

    def __init__(
        self, 
        vars: t.Dict[str, t.Any],
        parent: t.Dict[str, t.Any],
    ) -> None:
        self.vars = vars
        self.parent = parent

    def resolve_or_missing(self, key: str) -> t.Any:
        """Look up a variable by name, or return a missing sentinel."""
        if key in self.vars:
            return self.vars[key]
        if key in self.parent:
            return self.parent[key]
        return missing

    def contains(self, name: str) -> bool:
        """Check if a variable exists in this context."""
        return name in self.vars or name in self.parent

    def get_all(self) -> t.Dict[str, t.Any]:
        """Return the complete variable dict."""
        if not self.vars:
            return self.parent
        if not self.parent:
            return self.vars
        return dict(self.parent, **self.vars)


